#include <iostream>
#include <vector>

using namespace std;

int countMajoritySubarrays(vector<int> &nums, int target)
{
    int n = nums.size();
    int output = 0;
    for (int i = 0; i < n; ++i)
    {
        int count = 0;
        for (int j = i; j < n; ++j)
        {
            if (nums[j] == target)
            {
                ++count;
            }
            else
            {
                --count;
            }

            if (count > 0)
                ++output;
        }
    }

    return output;
}

